function sshBase64(bytes) {
  const alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';let out='';
  for(let i=0;i<bytes.length;i+=3){const a=bytes[i],b=bytes[i+1],c=bytes[i+2],n=(a<<16)|((b||0)<<8)|(c||0);out+=alphabet[(n>>>18)&63]+alphabet[(n>>>12)&63]+(b===undefined?'=':alphabet[(n>>>6)&63])+(c===undefined?'=':alphabet[n&63]);}
  return out;
}
const sshU32 = value => [(value>>>24)&255,(value>>>16)&255,(value>>>8)&255,value&255];
const sshU64 = value => [...sshU32(Math.floor(value/4294967296)),...sshU32(value%4294967296)];
const sshBytes = value => typeof value==='string' ? [...value].map(c=>c.charCodeAt(0)) : value;
const sshString = value => {const bytes=sshBytes(value);return [...sshU32(bytes.length),...bytes];};
const sshUserPublic = [...sshString('ssh-ed25519'),...sshString(Array.from({length:32},(_,i)=>i+1))];
const sshCaPublic = [...sshString('ssh-ed25519'),...sshString(Array.from({length:32},(_,i)=>160+i))];
function sshCertificate(serial,validAfter=sshEpoch-30,validBefore=sshEpoch+3600,principal='alice') {
  return sshBase64([
    ...sshString('ssh-ed25519-cert-v01@openssh.com'),...sshString(Array(32).fill(serial)),
    ...sshString(Array.from({length:32},(_,i)=>i+1)),...sshU64(serial),...sshU32(1),
    ...sshString(principal+'@corporate / reference certificate '+serial),...sshString(sshString(principal)),
    ...sshU64(validAfter),...sshU64(validBefore),...sshString([]),
    ...sshString([...sshString('permit-pty'),...sshString([])]),...sshString([]),...sshString(sshCaPublic),
    ...sshString([...sshString('ssh-ed25519'),...sshString(Array(64).fill(170))]),
  ]);
}

