function sshBuilder(meta,actors,initialState={}) {
  const definitions={},steps=[],values={},bindings={};
  const prefix='ssh'+meta.id.replace(/^lab-ssh-/,'').replace(/[^a-zA-Z0-9]/g,'_')+'_';
  const add=(key,name,meaning,origin,purpose,example,standard='RFC 4252',source=sshAuth,options={})=>{
    const id=prefix+key;
    definitions[id]={...labAttribute(name,meaning,origin,purpose,example,standard,source),
      creatorActorId:options.creator,holderActorIds:options.holders||[],permittedInspectorActorIds:options.inspectors||options.holders||[],
      disclosure:options.disclosure||'public-or-protected-message',simulationOnly:true};
    bindings[id]={instanceId:meta.id+':'+(options.instance||key),fieldPath:options.field||name,representation:options.representation||'decoded-local-value'};
    return id;
  };
  const ops=(kind,actorId,ids,detail,carriedAs)=>ids.map(item=>{
    const spec=typeof item==='string'?{id:item}:item,id=spec.id;
    return {attributeId:id,definitionId:id,kind,actorId,detail,...bindings[id],
      ...(spec.instance?{instanceId:meta.id+':'+spec.instance}:{}),...(spec.field?{fieldPath:spec.field}:{}),
      representation:spec.representation||(['send','receive'].includes(kind)?'wire-field':bindings[id].representation),
      value:spec.value===undefined?definitions[id].example:spec.value,
      creatorActorId:spec.creator||definitions[id].creatorActorId,holderActorIds:kind==='inspect'?[]:[actorId],
      permittedInspectorActorIds:definitions[id].permittedInspectorActorIds,disclosure:definitions[id].disclosure,...(carriedAs?{carriedAs}:{}),
    };
  });
  const wire=(ids,from,to,detail,carriedAs)=>[...ops('send',from,ids,detail,carriedAs),...ops('receive',to,ids,detail,carriedAs)];
  const payload=(ids,names)=>ids.map((item,i)=>{const spec=typeof item==='string'?{id:item}:item;return labP(names?.[i]||definitions[spec.id].name,spec.value===undefined?definitions[spec.id].example:spec.value,undefined,spec.id);});
  const stage=(key,title,from,to,summary,detail,operations,packet=[],effects=[],checks=[])=>{
    const eventId=meta.id+'-'+key;
    const enriched=operations.map((operation,index)=>{const exactValueRef=eventId+':'+index;values[exactValueRef]=operation.value;return {...operation,sourceEventId:eventId,exactValueRef};});
    const step=labStep(eventId,title,from,to,'ssh',from===to?'internal':'backchannel',summary,detail,[...new Set(enriched.map(o=>o.attributeId))],packet,checks,enriched);
    step.sshStage=key;step.interactionType=from===to?'local-operation':from==='user'||to==='user'?'human':(['sshAgent','pam','sssd'].includes(from)&&['sshCli','sshHost','pam','sssd'].includes(to))||(['sshAgent','pam','sssd'].includes(to)&&['sshCli','sshHost','pam','sssd'].includes(from))?'local-ipc':'network';
    step.protocolEffects=effects;steps.push(step);return step;
  };
  const local=(key,title,actor,summary,detail,operations,effects=[],checks=[])=>stage(key,title,actor,actor,summary,detail,operations,[],effects,checks);
  const send=(key,title,from,to,summary,detail,ids,effects=[],checks=[],carriedAs)=>stage(key,title,from,to,summary,detail,wire(ids,from,to,summary,carriedAs),payload(ids),effects,checks);
  const finish=()=>{
    const used=new Set(steps.flatMap(step=>step.fields));for(const id of Object.keys(definitions))if(!used.has(id))delete definitions[id];
    Object.assign(SSHLAB_ATTRIBUTES,definitions);
    const positions=Object.fromEntries(Object.entries(actors).map(([id,a])=>[id,a.position]));
    const model=labScenario({workspace:'ssh',family:'ssh-access',protocol:'ssh',architecture:'native',category:'SSH access',hasPerson:true,
      status:'standards-only',evidenceLevel:'reference',runtimeBindings:[],...meta,initialState:{protocolClock:sshEpoch,credentials:{},sessions:{},knowledge:{},policy:{},...initialState},protocolValues:values,positions},definitions,steps,actors);
    model.contextualize=context=>sshPersonalizeScenario(model,context);
    return model;
  };
  const setRuntimeBindings=runtimeBindings=>{meta.runtimeBindings=runtimeBindings;};
  const rebind=(id,instance,example)=>{bindings[id].instanceId=meta.id+':'+instance;if(example!==undefined)definitions[id].example=example;};
  return {add,ops,wire,payload,stage,local,send,finish,steps,definitions,setRuntimeBindings,rebind};
}

