  b.local('reissue-time','Advance protocol time before a fresh enrollment','sshCli','Reissuance is a new authentication/enrollment transaction.','The existing SSH connection remains separate. This explicit protocol clock event advances 120 seconds, regardless of playback speed.',b.ops('use','sshCli',[d.validBefore],'Inspect the remaining certificate lifetime.'),[sshAdvance(120)]);
  b.local('reissue-prepare','Keep key-1 and prepare a fresh PKCE transaction','sshCli','The local key identity is reused; the transaction secrets are fresh.','A user certificate is freshly enrolled/reissued. The host-certificate renewal operation is not applied to it.',[
    ...b.ops('use','sshCli',[d.privateKey,d.publicKey],'Reuse the existing protected local key-1.'),
    ...b.ops('create','sshCli',[verifier,state,nonce,redirect],'Create transaction-2 secrets and callback.'),...b.ops('derive','sshCli',[challenge],'Compute S256 for the new verifier.')
  ],[sshPut('transaction',{instanceId:id+':oidc-transaction-2',status:'pending',listenerOpen:true})]);
  const auth=[d.client,d.responseType,d.scope,redirect,state,nonce,challenge,d.challengeMethod];
  b.send('reissue-browser','Open the browser for a new approved enrollment','sshCli','browser','The native client requests a fresh, client-bound authorization.','A reused browser session does not automatically satisfy this fixture’s fresh-factor policy.',auth);
  b.send('reissue-authorize','Start the new OIDC transaction','browser','sshIdp','The IdP receives transaction-2’s nonce/state/challenge.','It keeps the new code binding separate from the completed first transaction.',auth);
  const factors=[{id:d.password,value:'<person-entered password>',instance:'factor-reissue-password'},{id:d.totp,value:'654321 (illustrative)',instance:'factor-reissue-totp'}];
  b.local('reissue-totp-compute','Compute a fresh second-factor code','totp','The enrolled authenticator produces the second ceremony’s code.','The fresh-factor policy is explicit; a valid SSO cookie is not enough for this reissuance preset.',b.ops('create','totp',[factors[1]],'Compute the new enrolled TOTP.'));
  b.send('reissue-totp-display','Display the fresh TOTP code','totp','user','The person reads the new second-factor code.','This is a separate factor occurrence bound to the new IdP ceremony.',[factors[1]]);
  b.send('reissue-factors','Require fresh password and TOTP approval','user','browser','The person completes the configured factors again.','This is the named policy: fresh factors for each enrollment, even if the IdP SSO cookie is valid.',factors);
  b.send('reissue-submit','Submit the new factor ceremony','browser','sshIdp','The IdP receives the second transaction’s factor inputs.','No CA success follows a failed or cancelled required factor.',factors);
  b.local('reissue-factor-check','Verify the fresh required factors','sshIdp','The new transaction achieves the configured policy.','Only after these checks does the IdP issue code-2.',[...b.ops('verify','sshIdp',factors,'Check fresh password and enrolled TOTP.'),...b.ops('create','sshIdp',[code],'Issue transaction-2 authorization code.')],[sshPut('transaction.factors',['pwd','otp'])]);
  b.send('reissue-redirect','Redirect code-2 to the browser','sshIdp','browser','The callback carries the second code and state.','The original code/transaction cannot stand in for this new callback.',[code,state,redirect]);
  b.send('reissue-callback','Deliver the new local callback','browser','sshCli','The browser calls the new initiating loopback listener.','The CLI checks state-2 and the new listener transaction.',[code,state,redirect]);
  b.local('reissue-callback-check','Check transaction-2 callback correlation','sshCli','The second callback matches its retained transaction.','Each native callback has independent correlation and lifetime.',b.ops('verify','sshCli',[state,redirect],'Verify the fresh callback.'),[sshPut('transaction.callbackAccepted',true)]);
  b.send('reissue-redeem','Redeem code-2 with verifier-2','sshCli','sshIdp','The CLI redeems the new code using its new verifier.','The old verifier does not bind this second code.',[d.grant,d.client,code,redirect,verifier]);
  b.local('reissue-token-issue','Validate PKCE and issue token-2','sshIdp','The IdP signs the new client-bound identity result.','The new nonce, issuance time and expiry belong to id-token-2.',[...b.ops('verify','sshIdp',[code,redirect,verifier,challenge,d.client],'Verify the second token request.'),...b.ops('create','sshIdp',[token,...claims],'Issue token-2 after the fresh policy.')]);
