    ...b.wire([token],'sshIdp','sshCli','Return token-2.'),...b.wire(claims,'sshIdp','sshCli','Claims carried inside token-2.','id_token claims'),...b.ops('verify','sshCli',[token,...claims],'Check issuer/signature/client audience/expiry/new nonce.')
