  b.send('reissue-enroll','Request a fresh user certificate for the existing key','sshCli','sshCa','The CA receives key-1’s same public bytes and token-2.','This is new issuance authorization. It does not mutate certificate-1 or replace key-1.',[d.publicKey,ott,d.certType,d.requestedPrincipals,...times]);
