  const newCert={id:d.cert,value:sshCertificate(2,sshEpoch+90,sshEpoch+3720),instance:'certificate-2'};
  const certFields=[newCert,{id:d.serial,value:2,instance:'certificate-2'},{id:d.principal,value:['alice'],instance:'certificate-2'},{id:d.validAfter,value:sshEpoch+90,instance:'certificate-2'},{id:d.validBefore,value:sshEpoch+3720,instance:'certificate-2'},{id:d.caSignature,value:'64 illustrative new signature bytes; simulation only',instance:'certificate-2'}];
  b.local('reissue-issue','Create certificate-2 / serial 2 / new validity','sshCa','The CA issues a new immutable user-certificate instance.','Existing key-1 retains identity and public bytes. Certificate-1 remains a historical object; reissuance is not in-place editing.',[...b.ops('use','sshCa',[d.caPrivate,d.publicKey],'Reuse issuer key and supplied user public key.'),...b.ops('create','sshCa',certFields,'Issue the fresh certificate-2.')],[sshAppend('credentials.certificateHistory',{instanceId:id+':certificate-1',serial:1}),sshPut('credentials.userCertificate',{instanceId:id+':certificate-2',serial:2,publicKeyInstance:id+':key-1',principals:['alice'],validAfter:sshEpoch+90,validBefore:sshEpoch+3720,status:'issued'}),sshPut('lifetimes.sshCertificate.expiresAt',sshEpoch+3720)]);
