  b.stage('reissue-install','Install certificate-2 with unchanged key-1','sshCli','sshAgent','The agent selects the new certificate with its original private key.','No private key is exported to the network and no existing SSH connection is reauthenticated by this installation.',[...b.wire([newCert],'sshCli','sshAgent','Install the new public certificate by local IPC.'),...b.ops('store','sshAgent',[d.privateKey,newCert],'Keep key-1 and new certificate-2 together.')],b.payload([newCert]),[sshPut('credentials.userCertificate.status','installed')]);
